deps in package.json

```json
"ts-node": "^10.9.1",
"tsconfig-paths": "^4.2.0",
"typeorm": "^0.3.20",
"npm-run-all": "^4.1.5",
```

command in package.json

```json
"build:dev": "nest build",
"_typeorm": "ts-node -r tsconfig-paths/register ./node_modules/typeorm/cli.js",
"orm:_run": "pnpm _typeorm -d ./src/database/source.config.ts migration:run",
"orm:run": "run-s build:dev orm:_run"
```

```ts
// source.config.ts
export default new DataSource({
  type: 'mysql',
  host: process.env.MYSQLHOST!,
  port: +process.env.MYSQLPORT!,
  username: process.env.MYSQLUSER!,
  password: process.env.MYSQL_ROOT_PASSWORD!,
  database: process.env.MYSQL_DATABASE!,
  synchronize: false,
  entities: ['dist/database/entity/*.js'],
  migrations: ['dist/database/migrations/*-target.js'],
  migrationsTableName: 'migrations',
})
```

