"totalCount":0}},{"content":"ROCKET","reactors":{"totalCount":0}},{"content":"EYES","reactors":{"totalCount":0}}]}]}},{"number":6294,"title":"QueryBuilder produces wrong SQL with order by + nested fields, breaks pagination-related queries with skip() and take()","url":"https://github.com/typeorm/typeorm/issues/6294","body":"**Issue type:**

