    LEFT JOIN "companies" "company" ON "company"."id"="person"."companyId"
    INNER JOIN "sale" "sale" ON "sale"."personUserId"="person"."userId"
    INNER JOIN "products" "product" ON "product"."id"="sale"."productId" AND ("product"."status" = $1 OR "product"."status" = $2)
    INNER JOIN "vendors" "vendor" ON "vendor"."userId"="product"."createdByVendorUserId"
    INNER JOIN "companies" "vendorCompany" ON "vendorCompany"."id"="vendor"."companyId"
    WHERE "vendorCompany"."id" = $3 
    GROUP BY "person"."id", "person"."userId", "sale"."id" 
    ORDER BY "person_userId" ASC, "sale_createdDate" DESC
  ) "distinctAlias"
