Every time I run `migration:generate` script, I always get the same enum updating SQL queries even though there are no changes in entity classes

### Expected Behavior

No migration file should be created if there are no changes in the entities directory

### Actual Behavior

The script generated this migration file

```js
module.exports = class TestFeature1718718747056 {
    name = 'TestFeature1718718747056'

    async up(queryRunner) {
        await queryRunner.query(`ALTER TYPE "public"."background_check_status_enum" RENAME TO "background_check_status_enum_old"`);
        await queryRunner.query(`CREATE TYPE "public"."background_check_status_enum" AS ENUM('unspecified', 'open', 'pendingClient', 'blocked', 'pendingOperation', 'rejected', 'unverifiable', 'completed', 'verified', 'expired')`);
        await queryRunner.query(`ALTER TABLE "background_check" ALTER COLUMN "status" DROP DEFAULT`);
        await queryRunner.query(`ALTER TABLE "background_check" ALTER COLUMN "status" TYPE "public"."background_check_status_enum" USING "status"::"text"::"public"."background_check_status_enum"`);
        await queryRunner.query(`ALTER TABLE "background_check" ALTER COLUMN "status" SET DEFAULT 'unspecified'`);
        await queryRunner.query(`DROP TYPE "public"."background_check_status_enum_old"`);
    }

    async down(queryRunner) {
        await queryRunner.query(`CREATE TYPE "public"."background_check_status_enum_old" AS ENUM('unspecified', 'open', 'pendingClient', 'blocked', 'pendingOperation', 'rejected', 'unverifiable', 'completed', 'verified', 'expired')`);
        await queryRunner.query(`ALTER TABLE "background_check" ALTER COLUMN "status" DROP DEFAULT`);
        await queryRunner.query(`ALTER TABLE "background_check" ALTER COLUMN "status" TYPE "public"."background_check_status_enum_old" USING "status"::"text"::"public"."background_check_status_enum_old"`);
        await queryRunner.query(`ALTER TABLE "background_check" ALTER COLUMN "status" SET DEFAULT 'unspecified'`);
        await queryRunner.query(`DROP TYPE "public"."background_check_status_enum"`);
        await queryRunner.query(`ALTER TYPE "public"."background_check_status_enum_old" RENAME TO "background_check_status_enum"`);
    }
}
```

### Steps to reproduce

1. have this model
```ts
import {
  Column,
  CreateDateColumn,
  DeleteDateColumn,
  Entity,
  Index,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
} from 'typeorm'

enum BackgroundCheckStatus {
  UNSPECIFIED = 'unspecified',
  OPEN = 'open',
  PENDING_CLIENT = 'pendingClient',
  BLOCKED = 'blocked',
  PENDING_OPERATION = 'pendingOperation',
  REJECTED = 'rejected',
  UNVERIFIABLE = 'unverifiable',
  COMPLETED = 'completed',
  VERIFIED = 'verified',
  EXPIRED = 'expired',
}

abstract class Model {
  @PrimaryGeneratedColumn('uuid')
  id: string

  @CreateDateColumn({ type: 'timestamptz', precision: 3 })
  createdAt: Date
  @UpdateDateColumn({ type: 'timestamptz', precision: 3 })
  updatedAt: Date
  @Index()
  @DeleteDateColumn({ type: 'timestamptz', precision: 3 })
  deletedAt: Date | null
}

@Entity()
export class BackgroundCheck extends Model {
  @Column({ type: 'varchar', nullable: true })
  ref?: string | null

  @Column({ type: 'jsonb', nullable: true })
  meta?: any

  @Column({
    type: 'enum',
    enum: BackgroundCheckStatus,
    default: BackgroundCheckStatus.UNSPECIFIED,
    enumName: 'background_check_status_enum',
  })
  status: BackgroundCheckStatus
}
```


2. Have a database that is already migrated once, all the tables in place
3. Run `yarn typeorm migration:generate -d src/db/dataSource.ts --outputJs`


