  VALUES (?, ?, ?, ?, ?, ?, NOW(), NOW())
  ON DUPLICATE KEY UPDATE 
    socket_id = VALUES(socket_id),
    is_active = VALUES(is_active),
    last_active = VALUES(last_active),
    updated_at = NOW()
  `,
  [userId, screenName, client.id, 1, new Date(), role],
);
